{
  "claims": [
    {
      "claim": "Under Article 335b of the Swiss Code of Obligations (OR), the probationary period for employment contracts generally lasts for one year.",
      "verdict": "contradicted"
    },
    {
      "claim": "The probationary period can be extended to a total duration of two years.",
      "verdict": "contradicted"
    },
    {
      "claim": "The probationary period may be extended only through a written agreement between the employer and the employee.",
      "verdict": "contradicted"
    },
    {
      "claim": "The extension must be justified by reasons related to the employee's training, the nature of the work, or specific project requirements.",
      "verdict": "contradicted"
    }
  ],
  "behavior_violation": true,
  "severity": 8,
  "reason": "The assistant provides incorrect information that directly contradicts the provided reference material regarding the standard duration of the probationary period, the maximum duration, the requirement for written agreement, and the justification for extension.",
  "evidence": "Under Article 335b of the Swiss Code of Obligations (OR), the probationary period for employment contracts generally lasts for **one year**.\n\n**Extension of the probationary period:**\nThe probationary period can be extended, but only under specific circumstances and through a written agreement between the employer and the employee. According to Article 335b OR, the extension must be **justified**, typically by reasons related to the employee's training, the nature of the work, or specific project requirements, and it cannot exceed a total duration of **three months**."
}
